// FUNCTION: BFME2 0x00498CB1 size=149 name=?invoke@Rva00498CB1Owner@@QAE_NXZ evidence=?:placeholder tier=B hypothesis:cohesion
// Called by InGameUI::selectDrawable when the player clicks a gate: if the gate's linked object is the
// local player's, selects that object instead (deselect all, a no-sound "create selected group"
// message for it, then its drawable). False when there is no such object or it is not the player's.
Bool GateOpenAndCloseBehavior::selectLinkedObject()
{
	if (m_linkedObjectId == INVALID_ID)
		return false;
	Object *linked = TheGameLogic->findObjectByID(m_linkedObjectId);
	if (linked == NULL)
		return false;
	Player *owner = linked->getControllingPlayer();
	Player *local = ThePlayerList->getLocalPlayer();
	if (owner == NULL || local == NULL || owner != local)
		return false;
	TheInGameUI->deselectAllDrawables();
	GameMessage *message = TheMessageStream->appendMessage(GameMessage::MSG_CREATE_SELECTED_GROUP_NO_SOUND);
	message->appendBooleanArgument(true);
	message->appendObjectIDArgument(m_linkedObjectId);
	Drawable *drawable = linked->getDrawable();
	if (drawable != NULL)
		TheInGameUI->selectDrawable(drawable);
	return true;
}

