// A repelling gate that is in the middle of its change pushes a movable unit away unless that unit
// is already heading for the gate or attacking it.
void GateOpenAndCloseBehavior::pushUnitAwayIfBlocking(Object *unit, Int, Int)
{
	if (!static_cast<const GateOpenAndCloseBehaviorModuleData *>(getModuleData())->m_repelCollidingUnits)
		return;
	if (m_2C != 1)
		return;
	if (!isPushableByGate(unit))
		return;
	AIUpdateInterface *ai = unit->m_ai;
	if (ai != NULL)
	{
		Object *goalGate = m_object;
		if (ai->getStateMachine()->getGoalObject() == goalGate)
			return;
		Object *victimGate = m_object;
		if (ai->getCurrentVictim() == victimGate)
			return;
	}
	moveUnitAwayFromGate(unit, 16.67f);
}

