// FUNCTION: BFME2 0x0049936A size=267 name=?onObjectCreated@GateOpenAndCloseBehavior@@UAEXXZ evidence=N:ledger tier=B hypothesis:cohesion
// A gate whose owner is already dead opens for good and leaves the gate list; otherwise the gate
// finds its partner by the Proxy name in the module data and the two link each other's object ids.
void GateOpenAndCloseBehavior::onObjectCreated()
{
	BehaviorModule::loadPostProcess();

	if (m_object == NULL)
		return;

	if (m_object->isEffectivelyDead())
	{
		rva004992D5(true, true);
		TheSkirmishAIManager->m_gateList->rva004E908C(this);
	}

	const GateOpenAndCloseBehaviorModuleData *data = static_cast<const GateOpenAndCloseBehaviorModuleData *>(getModuleData());
	if (data->m_proxy.isEmpty())
		return;

	Object *candidate = TheGameLogic->getFirstObject();
	AsciiString candidateName;
	while (candidate != NULL)
	{
		candidateName = candidate->m_name;
		if (candidateName.compare(data->m_proxy) == 0)
		{
			static NameKeyType gateKey = TheNameKeyGenerator->nameToKey("GateProxyBehavior");
			GateOpenAndCloseBehavior *other = static_cast<GateOpenAndCloseBehavior *>(candidate->findUpdateModule(gateKey));
			if (other != NULL)
			{
				other->m_linkedObjectId = m_object->getID();
				m_linkedObjectId = candidate->getID();
			}
			break;
		}
		candidate = candidate->getNextObject();
	}
}

